(function(){let t=0,o=0,n=240,s=160,i=0,c=0,a=0;return{init:function(r){t=r,o=0;const e=1+.4*t;n=240,s=160,i=1.3*e,c=1.7*e,a=0},draw:function(h){"ram";const r=3+t,e=1+.4*t,l=55;if(h.setColor(3),o>0){h.setColor(0);for(let t=0;t<r;t++){const o=a+6.283*t/r,i=a+6.283*(t+1)/r;h.drawLine(n+l*Math.cos(o)|0,s+l*Math.sin(o)|0,n+l*Math.cos(i)|0,s+l*Math.sin(i)|0)}h.setColor(3)}n+=i,s+=c,a+=.05*e,(n<l||n>425)&&(i=-i),(s<l||s>265)&&(c=-c),n=E.clip(n,l,425),s=E.clip(s,l,265);for(let t=0;t<r;t++){const o=a+6.283*t/r,i=a+6.283*(t+1)/r;h.drawLine(n+l*Math.cos(o)|0,s+l*Math.sin(o)|0,n+l*Math.cos(i)|0,s+l*Math.sin(i)|0)}o++}}});